def value_iteration(mdp, gamma=0.9, iterations=100):
    values = {state: 0.0 for state in mdp}

    for _ in range(iterations):
        updated = values.copy()
        for state, actions in mdp.items():
            if not actions:
                updated[state] = 0.0
                continue

            action_values = []
            for outcomes in actions.values():
                expected = 0.0
                for probability, next_state, reward, terminated in outcomes:
                    future = 0.0 if terminated else values[next_state]
                    expected += probability * (reward + gamma * future)
                action_values.append(expected)

            updated[state] = max(action_values)
        values = updated

    return values

print(value_iteration(mdp))

def extract_greedy_policy(mdp, values, gamma=0.9):
    policy = {}
    for state, actions in mdp.items():
        if not actions:
            continue

        best_action = None
        best_value = float('-inf')
        for action, outcomes in actions.items():
            expected = 0.0
            for probability, next_state, reward, terminated in outcomes:
                future = 0.0 if terminated else values[next_state]
                expected += probability * (reward + gamma * future)
            if expected > best_value:
                best_value = expected
                best_action = action
        policy[state] = best_action

    return policy

values = value_iteration(mdp)
print(extract_greedy_policy(mdp, values))
